SELECT game_id AS "gameId", entity_id AS "entityId", provider_id AS "providerId", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.entity_provider_mounts WHERE game_id = #{gameId}
AND entity_id = #{entityId}
AND provider_id = #{providerId}
ORDER BY entity_id, provider_id

